def forward(groups):
    size = float(groups[0])
    unit = groups[1]
    multiplier = {'B': 1, 'KB': 1024, 'MB': 1024**2}[unit]
    return {'stored': [int(round(size * multiplier))], 'layout': []}

def inverse(record):
    size_in_bytes = int(record['stored'][0])
    if size_in_bytes >= 1024**2:
        return f'{size_in_bytes / 1024**2:.1f} MB'
    elif size_in_bytes >= 1024:
        return f'{size_in_bytes / 1024:.1f} KB'
    else:
        return f'{size_in_bytes} B'
